class Solution:
 def countSubstrings(self,s):
  ans=0
  for c in range(len(s)):
   for l,r in ((c,c),(c,c+1)):
    while l>=0 and r<len(s) and s[l]==s[r]:ans+=1;l-=1;r+=1
  return ans

class Solution:
 def replaceWords(self,dictionary,sentence):
  roots=set(dictionary);out=[]
  for word in sentence.split():out.append(next((word[:i] for i in range(1,len(word)+1) if word[:i] in roots),word))
  return ' '.join(out)

