class Solution:
 def predictPartyVictory(self,senate):
  n=len(senate);r=deque(i for i,c in enumerate(senate) if c=='R');d=deque(i for i,c in enumerate(senate) if c=='D')
  while r and d:
   a,b=r.popleft(),d.popleft()
   (r if a<b else d).append((a if a<b else b)+n)
  return 'Radiant' if r else 'Dire'

class Solution:
 def minSteps(self,n):
  ans=0;p=2
  while p*p<=n:
   while n%p==0:ans+=p;n//=p
   p+=1
  return ans+n if n>1 else ans

class Solution:
 def findDuplicateSubtrees(self,root):
  ids={};counts={};out=[]
  def dfs(n):
   if n is None:return 0
   key=(n.val,dfs(n.left),dfs(n.right));i=ids.setdefault(key,len(ids)+1);counts[i]=counts.get(i,0)+1
   if counts[i]==2:out.append(n)
   return i
  dfs(root);return out

class Solution:
 def findTarget(self,root,k):
  seen=set()
